//! Shared ABI (version 1) for the site's WebAssembly kernels.
//!
//! Every kernel module (`signal.wasm`, `information.wasm`, `dynamics.wasm`) is a
//! `no_std` `cdylib` with **zero imports**. It exports its linear `memory`, the
//! four ABI functions generated by [`export_abi!`] and its own numeric kernels.
//!
//! * Pointers are `u32` byte offsets into linear memory and must reference memory
//!   obtained from `arena_alloc` since the last `arena_reset` ([`mem`]).
//! * Fallible `i32` functions return a status code ([`Error::code`]).
//! * `f64` functions return `NaN` for invalid arguments and documented values for
//!   degenerate (e.g. empty) inputs.
//!
//! See `docs/adr/0003-wasm-kernels.md` for the full contract.
#![cfg_attr(not(test), no_std)]

pub mod arena;
pub mod mem;

/// Version of the binary interface implemented by every kernel module.
pub const ABI_VERSION: u32 = 1;

/// Status code for success.
pub const OK: i32 = 0;

/// Reasons a kernel call can fail. The discriminants are the ABI status codes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(i32)]
pub enum Error {
    /// `-1`: a length is zero where an empty buffer has no meaning, or exceeds a documented limit.
    InvalidLength = -1,
    /// `-2`: a transform length is not a power of two.
    NotPowerOfTwo = -2,
    /// `-3`: the arena could not grow linear memory for scratch space.
    OutOfMemory = -3,
    /// `-4`: a parameter is out of range or not finite, or a pointer does not reference
    /// a live, aligned, non-overlapping arena region.
    InvalidParameter = -4,
}

impl Error {
    /// The ABI status code (a negative `i32`).
    #[must_use]
    pub const fn code(self) -> i32 {
        self as i32
    }
}

/// Result type used by the kernels' internal wrappers.
pub type KResult<T = ()> = Result<T, Error>;

/// Converts a wrapper result into an ABI status code (`0` or a negative [`Error`] code).
#[must_use]
pub const fn status(result: KResult) -> i32 {
    match result {
        Ok(()) => OK,
        Err(e) => e.code(),
    }
}

/// Converts a result carrying a non-negative count into an `i32` (count or error code).
#[must_use]
pub fn count_status(result: KResult<u32>) -> i32 {
    match result {
        Ok(n) => i32::try_from(n).unwrap_or(i32::MAX),
        Err(e) => e.code(),
    }
}

/// Returns `Ok(x)` when `x` is finite, otherwise [`Error::InvalidParameter`].
pub fn finite(x: f64) -> KResult<f64> {
    if x.is_finite() {
        Ok(x)
    } else {
        Err(Error::InvalidParameter)
    }
}

/// Terminates execution. On wasm32 this is the `unreachable` instruction, which traps
/// without pulling in any panic or formatting machinery (so modules keep zero imports).
#[inline(always)]
pub fn abort() -> ! {
    #[cfg(target_arch = "wasm32")]
    core::arch::wasm32::unreachable();
    #[cfg(not(target_arch = "wasm32"))]
    loop {
        core::hint::spin_loop();
    }
}

/// Generates the ABI v1 exports (`abi_version`, `arena_alloc`, `arena_reset`,
/// `arena_used`) and, outside of tests, the `#[panic_handler]`.
///
/// Must be invoked exactly once, at the root of each kernel `cdylib`.
#[macro_export]
macro_rules! export_abi {
    () => {
        /// ABI version implemented by this module (always `1`).
        #[unsafe(no_mangle)]
        pub extern "C" fn abi_version() -> u32 {
            $crate::ABI_VERSION
        }

        /// Bump-allocates `bytes` bytes aligned to `align` (a power of two) in linear
        /// memory, growing it when needed. Returns the byte offset, or `0` on failure
        /// (alignment not a power of two, or memory cannot grow). Contents are unspecified.
        #[unsafe(no_mangle)]
        pub extern "C" fn arena_alloc(bytes: u32, align: u32) -> u32 {
            $crate::arena::alloc(bytes, align)
        }

        /// Frees every transient arena allocation (persistent kernel state, such as the
        /// flow field of `dynamics.wasm`, is kept).
        #[unsafe(no_mangle)]
        pub extern "C" fn arena_reset() {
            $crate::arena::reset()
        }

        /// Bytes currently allocated in the arena (transient and persistent).
        #[unsafe(no_mangle)]
        pub extern "C" fn arena_used() -> u32 {
            $crate::arena::used()
        }

        #[cfg(not(test))]
        #[panic_handler]
        fn panic(_info: &core::panic::PanicInfo<'_>) -> ! {
            $crate::abort()
        }
    };
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn status_codes_match_abi() {
        assert_eq!(status(Ok(())), 0);
        assert_eq!(Error::InvalidLength.code(), -1);
        assert_eq!(Error::NotPowerOfTwo.code(), -2);
        assert_eq!(Error::OutOfMemory.code(), -3);
        assert_eq!(Error::InvalidParameter.code(), -4);
        assert_eq!(count_status(Ok(7)), 7);
        assert_eq!(count_status(Ok(u32::MAX)), i32::MAX);
        assert_eq!(count_status(Err(Error::InvalidLength)), -1);
    }

    #[test]
    fn finite_rejects_nan_and_infinity() {
        assert_eq!(finite(1.5), Ok(1.5));
        assert_eq!(finite(f64::NAN), Err(Error::InvalidParameter));
        assert_eq!(finite(f64::INFINITY), Err(Error::InvalidParameter));
    }
}
